    std::uint64_t aWandererI = 0U; std::uint64_t aWandererJ = 0U; std::uint64_t aWandererK = 0U;

    // [twist]
    aIngress = 0xEDE4F0BADB9F911AULL;
    aCarry = 0xD677C6F524A1F077ULL;
    aWandererA = 0xB0C82E689D3B5CFDULL;
