    TwistExpander_Altair_Arx::TWIST_A(PARAMS_TWIST);

    TwistExpander_Altair_Arx::TWIST_B(PARAMS_TWIST);

    TwistExpander_Altair_Arx::TWIST_C(PARAMS_TWIST);

    //
    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectA;
