    TwistExpander_Altair_Arx::TWIST_D(PARAMS_TWIST);

    TwistExpander_Altair_Arx::TWIST_E(PARAMS_TWIST);

    TwistExpander_Altair_Arx::TWIST_F(PARAMS_TWIST);

